#!/bin/sh
# The header of an idea (agent_plans/_ideas/<slug>.md; contract, "Idea header"), written by a
# script so that "Open questions:" does not depend on someone counting right.
# Usage:
#   sh idea.sh count <file>
#       prints how many questions are open: the top-level list items (a line that starts with
#       "- ", "* " or "<n>. ") of the section marked by <!-- open-questions -->, from the
#       marker to the next "# " or "## " heading; items inside a ``` block do not count
#   sh idea.sh sync <file>
#       writes that count to "Open questions:" (the first one in the header; without it, right
#       after "Created:", or "Status:", or on the first line)
#   sh idea.sh status <file> <open|refining|ready|mapped> [plan]
#       changes "Status:"; with mapped, the plan (agent_plans/<name>) is required and goes to "Plan:".
#       Refuses (exit 2) only what the contract forbids: mapped without a plan and leaving mapped
#       (mapped again, with another plan, changes "Plan:"). ready with "Open questions:" above 0, or
#       with no number, warns on stderr and accepts: the person is the one who confirms
# The header is the lines before the first "# "; the rest of the file does not change.
# Exits 0; 1 when the file is missing or has no marker; 2 on wrong usage or a value outside the
# contract. On error, the file stays as it was. Messages are in the package language.

language='pt-BR'
# >>> strings (area idea.): generated by tools/script-strings.sh from core/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='idea.usage	x-test:idea.usage
idea.notFound	x-test:idea.notFound {0}
idea.noMarker	x-test:idea.noMarker {0}
idea.planSoMapped	x-test:idea.planSoMapped
idea.mappedWithoutPlan	x-test:idea.mappedWithoutPlan
idea.invalidState	x-test:idea.invalidState {0}
idea.alreadyMapped	x-test:idea.alreadyMapped {0} {1}
idea.warnUnknown	x-test:idea.warnUnknown
idea.warnOpen	x-test:idea.warnOpen {0}
' ;;
  pt-BR) MSG_TABLE='idea.usage	Uso: sh idea.sh count <arquivo> | sync <arquivo> | status <arquivo> <open|refining|ready|mapped> [plano]
idea.notFound	idea.sh: {0} não existe
idea.noMarker	idea.sh: {0} não tem o marcador <!-- open-questions -->
idea.planSoMapped	idea.sh: Plan: só se escreve com mapped
idea.mappedWithoutPlan	idea.sh: mapped pede o caminho do plano (agent_plans/<nome>)
idea.invalidState	idea.sh: «{0}» não é estado de ideia (open, refining, ready, mapped)
idea.alreadyMapped	idea.sh: {0} já está mapped (Plan: {1}); mapped é final, mapear de novo gera um plano novo
idea.warnUnknown	idea.sh: aviso: Open questions: desconhecido; ready mesmo assim
idea.warnOpen	idea.sh: aviso: Open questions: {0}; ready mesmo assim
' ;;
  *) MSG_TABLE='idea.usage	Usage: sh idea.sh count <file> | sync <file> | status <file> <open|refining|ready|mapped> [plan]
idea.notFound	idea.sh: {0} does not exist
idea.noMarker	idea.sh: {0} has no <!-- open-questions --> marker
idea.planSoMapped	idea.sh: Plan: is only written with mapped
idea.mappedWithoutPlan	idea.sh: mapped needs the plan path (agent_plans/<name>)
idea.invalidState	idea.sh: "{0}" is not an idea state (open, refining, ready, mapped)
idea.alreadyMapped	idea.sh: {0} is already mapped (Plan: {1}); mapped is final, mapping again creates a new plan
idea.warnUnknown	idea.sh: warning: Open questions: unknown; ready anyway
idea.warnOpen	idea.sh: warning: Open questions: {0}; ready anyway
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings

usage() { msg idea.usage >&2; exit 2; }

[ $# -ge 2 ] || usage
action=$1
file=$2
[ -n "$file" ] || usage
case "$action" in count|sync|status) ;; *) usage ;; esac
[ -f "$file" ] || { msg idea.notFound "$file" >&2; exit 1; }

# count_open: prints the count; exits 1 without the marker
count_open() {
  awk '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t\r]+$/, "", s); return s }
    !found { if (trim($0) == "<!-- open-questions -->") found = 1; next }
    /^```/ { in_code = !in_code; next }
    in_code { next }
    /^# / || /^## / { exit }
    /^[-*] / || /^[0-9]+\. / { n++ }
    END { if (!found) exit 1; print n + 0 }
  ' "$1"
}

# read_key <file> <key>: the value of the last "<key>: …" line of the header (empty without it)
read_key() {
  awk -v key="$2" '
    /^# / { exit }
    substr($0, 1, length(key) + 2) == key ": " { v = substr($0, length(key) + 3); sub(/[ \t\r]+$/, "", v); found = 1 }
    END { if (found) print v }
  ' "$1"
}

# write_key <file> <key> <value> [key to insert after…]: replaces the last "<key>: …" line of
# the header, the one read_key reads; without it, inserts after the first key of the list that
# exists, or on the first line
write_key() {
  w_file=$1 w_key=$2 w_value=$3
  shift 3
  w_tmp="$w_file.idea-tmp.$$"
  awk -v key="$w_key" -v value="$w_value" -v after="$*" '
    { l[NR] = $0 }
    END {
      end_head = NR + 1
      for (i = 1; i <= NR; i++) if (l[i] ~ /^# /) { end_head = i; break }
      prefix = key ":"
      target = 0
      for (i = 1; i < end_head; i++) if (substr(l[i], 1, length(prefix)) == prefix) target = i
      pos = 0
      if (!target) {
        k = split(after, d, " ")
        for (j = 1; j <= k && !pos; j++)
          for (i = 1; i < end_head; i++) if (substr(l[i], 1, length(d[j]) + 1) == d[j] ":") { pos = i; break }
      }
      line = key ": " value
      if (!target && pos == 0) print line
      for (i = 1; i <= NR; i++) {
        if (i == target) print line; else print l[i]
        if (!target && i == pos) print line
      }
    }
  ' "$w_file" > "$w_tmp" || { rm -f "$w_tmp"; exit 1; }
  # cat instead of mv: the file keeps its mode and links
  cat "$w_tmp" > "$w_file" || { rm -f "$w_tmp"; exit 1; }
  rm -f "$w_tmp"
}

case "$action" in
  count)
    [ $# -eq 2 ] || usage
    count_open "$file" || { msg idea.noMarker "$file" >&2; exit 1; }
    ;;
  sync)
    [ $# -eq 2 ] || usage
    n=$(count_open "$file") || { msg idea.noMarker "$file" >&2; exit 1; }
    write_key "$file" "Open questions" "$n" Created Status
    ;;
  status)
    case $# in 3|4) ;; *) usage ;; esac
    state=$3
    plan=${4-}
    case "$state" in
      open|refining|ready) [ -z "$plan" ] || { msg idea.planSoMapped >&2; exit 2; } ;;
      mapped)
        while :; do case "$plan" in */) plan=${plan%/} ;; *) break ;; esac; done
        [ -n "$plan" ] || { msg idea.mappedWithoutPlan >&2; exit 2; }
        ;;
      *) msg idea.invalidState "$state" >&2; exit 2 ;;
    esac
    # mapped is final (contract): mapping again changes Plan:, but there is no going back to another state
    if [ "$state" != mapped ] && [ "$(read_key "$file" Status)" = mapped ]; then
      msg idea.alreadyMapped "$file" "$(read_key "$file" Plan)" >&2
      exit 2
    fi
    # ready with questions: the person confirms, so it only warns
    if [ "$state" = ready ]; then
      n=$(read_key "$file" "Open questions")
      case "$n" in
        0) ;;
        ''|*[!0-9]*) msg idea.warnUnknown >&2 ;;
        *) msg idea.warnOpen "$n" >&2 ;;
      esac
    fi
    write_key "$file" Status "$state"
    [ "$state" = mapped ] && write_key "$file" Plan "$plan" Status
    ;;
esac
exit 0
